import React from 'react';
import './Work.css';

function Work() {
  const projects = [
    {
      title: 'AI Vibe Coding Workshop',
      description: 'Designed and led a hands-on workshop for 50+ students, developing curriculum that balanced theory with practical AI applications.',
      result: '95% participant satisfaction'
    },
    {
      title: 'Harvard Business Simulation',
      description: 'Led a cross-functional team through a multi-phase business strategy simulation, applying data-driven decision frameworks under pressure.',
      result: 'Top performance in strategic planning'
    },
    {
      title: 'Women in Business Mentorship',
      description: 'Established a structured mentorship program with regular one-on-one sessions focused on career strategy and professional growth.',
      result: '10+ students mentored'
    }
  ];

  return (
    <section id="work" className="work">
      <h2>Featured Work</h2>

      <div className="work-grid">
        {projects.map((project, index) => (
          <div key={index} className="work-item">
            <h3>{project.title}</h3>
            <p className="work-description">{project.description}</p>
            <div className="work-result">{project.result}</div>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Work;
